INSERT INTO `mensajes_ia` (`id_mensaje`, `id_conversacion`, `emisor`, `contexto`, `solicitud`, `respuesta`, `informacion_clave`, `fecha_envio`) VALUES
(1, 1, 'usuario', NULL, '[usuario] Que esta agotado o en stock bajo', NULL, NULL, '2026-06-20 15:42:49'),
(2, 1, 'usuario', NULL, '[ia] 📦 Estado del Inventario\n\n\nTotal productos: 7\n\n✅ Con stock: 7\n\n❌ Agotados: 0\n\n🏆 Mayor stock: Galletas Natys Saladitas queso chedar 90g (5100 cajas)\n\n\nStock bajo (≤5 cajas):⚠️ Elefante Php1: 5 cajas', NULL, NULL, '2026-06-20 15:42:49'),
(3, 1, NULL, NULL, 'Que esta agotado o en stock bajo', '📦 Estado del Inventario\n\n\nTotal productos: 7\n\n✅ Con stock: 7\n\n❌ Agotados: 0\n\n🏆 Mayor stock: Galletas Natys Saladitas queso chedar 90g (5100 cajas)\n\n\nStock bajo (≤5 cajas):⚠️ Elefante Php1: 5 cajas', NULL, '2026-06-20 15:49:04'),
(4, 1, NULL, NULL, 'Cuales son las ventas de hoy', '💰 Resumen de Pagos\n\n\n📅 Hoy: 0 pagos — $0.00\n\n🗓️ Este mes: 7 pagos — $1,627.50\n\n⏳ Pendientes:', NULL, '2026-06-20 15:49:10'),
(5, 1, NULL, NULL, 'Que productos tenemos disponibles', '<b>Estado del Inventario</b><br><br>\nTotal productos: <b>7</b><br>\n Con stock: <b>7</b><br>\n Agotados: <b>0</b><br>\n Mayor stock: <b>Galletas Natys Saladitas queso chedar 90g</b> (5100 cajas)<br><br>\n<b>Stock bajo (≤5 cajas):</b><ul><li> Elefante Php1: <b>5</b> cajas</li></ul>', NULL, '2026-06-23 23:47:00'),
(6, 1, NULL, NULL, 'Que productos tenemos disponibles', 'Estado del Inventario\nTotal productos: 7\nCon stock: 7\nAgotados: 0\nMayor stock: Galletas Natys Saladitas queso chedar 90g (5100 cajas)\nStock bajo (≤5 cajas): Elefante Php1: 5 cajas', NULL, '2026-06-23 23:49:31'),
(7, 1, NULL, 'Inventario', 'Que esta agotado o en stock bajo', 'Estado del Inventario\nTotal productos: 7\nCon stock: 7\nAgotados: 0\nMayor stock: Galletas Natys Saladitas queso chedar 90g (5100 cajas)\nStock bajo (≤5 cajas): Elefante Php1: 5 cajas', NULL, '2026-06-23 23:54:02'),
(13, 5, 'usuario', 'Ayuda', 'Hola, soy el administrador Elias', '', 'Elías es administrador.', '2026-09-11 21:33:04'),
(14, 5, 'ia', NULL, '', '¡Hola, Elías! Es un gusto saludarte. Como administrador, tienes acceso a todas las funciones del sistema Larence. ¿En qué puedo ayudarte hoy? ¿Necesitas revisar alguna información, generar un reporte o tienes alguna consulta específica? Estoy aquí para asistirte.', NULL, '2026-09-11 21:33:04'),
(15, 5, 'usuario', 'Ventas/Pagos', '¿Cuáles fueron las ventas (pedidos) del mes y dame recomendaciones?', '', 'El nombre del usuario es Elías.', '2026-09-11 21:33:52'),
(16, 5, 'ia', NULL, '', '¡Hola, Elías!\n\nLas ventas (pedidos) de este mes han sido de **$1725.00**.\n\n📌 **Recomendaciones:**\n*   **Analizar el detalle de las ventas:** Sería útil revisar qué productos o categorías son los más vendidos para identificar patrones y oportunidades.\n*   **Evaluar la efectividad de promociones:** Si hay promociones activas, podríamos analizar su impacto en estas ventas y considerar ajustarlas para el próximo mes.\n*   **Identificar clientes clave:** Podríamos buscar qué clientes han contribuido más a estas ventas para fidelizarlos y ofrecerles un trato preferencial.\n\n¿Te gustaría que profundicemos en alguno de estos puntos o tienes alguna otra consulta?', NULL, '2026-09-11 21:33:53'),
(17, 5, 'usuario', 'Ayuda', 'Hola, soy el administrador Elias', '', 'Elías es el administrador.', '2026-09-11 21:34:07'),
(18, 5, 'ia', NULL, '', '¡Hola, Elías! Es un gusto saludarte nuevamente. Como administrador, tienes acceso a todas las funciones del sistema Larence. Estoy aquí para ayudarte con lo que necesites.\n\n¿Hay algo en particular que te gustaría revisar hoy? Tal vez:\n\n*   **Consultar información** sobre clientes, productos, pedidos, etc.\n*   **Generar algún reporte** o informe.\n*   **Analizar datos** para tomar decisiones.\n\n¡No dudes en preguntarme!', NULL, '2026-09-11 21:34:07'),
(19, 5, 'usuario', 'Ventas/Pagos', '¿Cuáles fueron las ventas (pedidos) del mes y dame recomendaciones?', '', 'El nombre del usuario es Elías.', '2026-09-11 21:34:15'),
(20, 5, 'ia', NULL, '', '¡Hola, Elías!\n\nLas ventas (pedidos) de este mes han sido de **$1725.00**.\n\n📌 **Recomendaciones:**\n*   **Analizar el detalle de las ventas:** Sería útil revisar qué productos o categorías son los más vendidos para identificar patrones y oportunidades.\n*   **Evaluar la efectividad de promociones:** Si hay promociones activas, podríamos analizar su impacto en estas ventas y considerar ajustarlas para el próximo mes.\n*   **Identificar clientes clave:** Podríamos buscar qué clientes han contribuido más a estas ventas para fidelizarlos y ofrecerles un trato preferencial.\n\n¿Te gustaría que profundicemos en alguno de estos puntos o tienes alguna otra consulta?', NULL, '2026-09-11 21:34:15'),
(21, 5, 'usuario', 'Clientes', 'Genera un reporte PDF con el resumen de clientes por tipo', '', NULL, '2026-09-11 21:34:21'),
(22, 5, 'ia', NULL, '', '¡Claro, Elías! Aquí tienes el resumen de clientes por tipo:\n\n*   **Bodegas:** 4 clientes\n*   **Distribuidores:** 2 clientes\n*   **Empresas:** 3 clientes\n*   **Franquicia multiple:** 2 clientes\n*   **Sucursales:** 1 cliente\n\n<<<REPORTE>>>{\"titulo\":\"Resumen de Clientes por Tipo\",\"columnas\":[\"Tipo de Cliente\",\"Cantidad de Clientes\"],\"filas\":[[\"Bodegas\",4],[\"Distribuidores\",2],[\"Empresas\",3],[\"Franquicia multiple\",2],[\"Sucursales\",1]],\"totales\":{},\"notas\":[\"Este reporte muestra la distribución de clientes según su tipo.\",\"Útil para entender la segmentación de la base de clientes.\"]}', NULL, '2026-09-11 21:34:22'),
(23, 5, 'usuario', 'Ayuda', 'Hola, soy el administrador Elias', '', NULL, '2026-09-11 21:39:57'),
(24, 5, 'ia', NULL, '', '¡Hola, Elías! Es un gusto saludarte nuevamente. Como administrador, tienes acceso completo al sistema Larence.\n\n¿Hay algo en lo que pueda ayudarte hoy? ¿Necesitas alguna información, un reporte o tienes alguna pregunta específica? Estoy aquí para asistirte.', NULL, '2026-09-11 21:39:57'),
(25, 5, 'usuario', 'Ventas/Pagos', '¿Cuáles fueron las ventas (pedidos) del mes y dame recomendaciones?', '', NULL, '2026-09-11 21:40:17'),
(26, 5, 'ia', NULL, '', '¡Hola, Elías!\n\nParece que hubo un inconveniente al intentar obtener los datos de las ventas del mes. El sistema me indica un error relacionado con una columna `status_entrega`.\n\nDebido a este error, no puedo proporcionarte las cifras exactas de ventas ni las recomendaciones en este momento.\n\n¿Te gustaría que intente obtener la información de las ventas de otra manera, o hay algo más en lo que pueda ayudarte?', NULL, '2026-09-11 21:40:17'),
(27, 5, 'usuario', 'Clientes', 'Genera un reporte PDF con el resumen de clientes por tipo', '', NULL, '2026-09-11 21:40:50'),
(28, 5, 'ia', NULL, '', '¡Claro, Elías! Aquí tienes el resumen de clientes por tipo:\n\n*   **Bodegas:** 4 clientes\n*   **Empresas:** 3 clientes\n*   **Franquicia múltiple:** 2 clientes\n*   **Sucursales:** 1 cliente\n*   **Distribuidores:** 1 cliente\n\n<<<REPORTE>>>{\"titulo\":\"Resumen de Clientes por Tipo\",\"columnas\":[\"Tipo de Cliente\",\"Cantidad de Clientes\"],\"filas\":[[\"Bodegas\",4],[\"Empresas\",3],[\"Franquicia multiple\",2],[\"Sucursales\",1],[\"Distribuidores\",1]],\"totales\":{},\"notas\":[\"Este reporte muestra la distribución de clientes según su tipo.\",\"Útil para entender la segmentación de la base de clientes.\"]}', NULL, '2026-09-11 21:40:50'),
(29, 5, 'usuario', 'Clientes', 'Ojo, mi cliente favorito es Distribuidora Andina y le gusta el crédito a 30 días', '', 'Ojo, mi cliente favorito es Distribuidora Andina y le gusta el crédito a 30 días', '2026-09-11 21:42:09'),
(30, 5, 'ia', NULL, '', '¡Excelente información, Elías! He tomado nota de que Distribuidora Andina es tu cliente favorito y que prefieren crédito a 30 días. Es muy útil conocer estos detalles para brindarles una atención personalizada.\n\nMe aseguraré de tener esto en cuenta en futuras interacciones y consultas relacionadas con este cliente.\n\n¿Hay algo más en lo que pueda ayudarte hoy?', NULL, '2026-09-11 21:42:09'),
(31, 6, 'usuario', 'Clientes', 'Ojo, mi cliente favorito es Distribuidora Andina y le gusta el credito a 30 dias', '', 'Ojo, mi cliente favorito es Distribuidora Andina y le gusta el credito a 30 dias', '2026-09-11 21:48:10'),
(32, 6, 'ia', NULL, '', '¡Excelente información! Me anoto que Distribuidora Andina es tu cliente favorito y que prefiere crédito a 30 días. Esto me ayudará a brindarte un mejor servicio y a tenerlo en cuenta en futuras interacciones.\n\n¿Hay algo más en lo que pueda ayudarte hoy con Distribuidora Andina o con cualquier otra consulta?', NULL, '2026-09-11 21:48:10'),
(33, 6, 'usuario', 'Clientes', 'Que sabes de mis clientes? Recomiendame a cual ofrecer promociones.', '', NULL, '2026-09-11 21:48:52'),
(34, 6, 'ia', NULL, '', '¡Claro! Aquí tienes un resumen de tus clientes con mayor actividad y potencial:\n\n### Clientes con mayor volumen de compra:\n\n*   **Elite bien**: Con 6 pedidos y un total de $2481.00.\n*   **Farmatodo**: También con 6 pedidos y un total de $1702.50.\n*   **Miguel Bose**: Con 3 pedidos y un total de $1213.50.\n\n### 📌 Recomendaciones:\n\nPara ofrecer promociones, te sugiero lo siguiente:\n\n1.  **Clientes de alto valor (Elite bien, Farmatodo, Miguel Bose):** Ofrece promociones exclusivas o descuentos por volumen para recompensar su lealtad y fomentar compras aún mayores. Podrías considerar paquetes de productos o descuentos progresivos.\n2.  **Clientes con menor actividad (PaTodo, Gabriela Hernandez):** Podrías intentar reactivarlos con promociones de bienvenida o descuentos en su próxima compra para incentivarlos a realizar nuevos pedidos.\n3.  **Clientes sin actividad (Jesus andrade, @superusuario_24, William):** Sería útil investigar por qué no han realizado pedidos y, si es posible, contactarlos para entender sus necesidades y ofrecerles una promoción de \"primer pedido\" o un descuento especial para animarlos a probar tus productos.\n\n¡Espero que esto te sea de gran ayuda para tus estrategias de promoción!', NULL, '2026-09-11 21:48:52'),
(35, 1, NULL, 'General', 'Dime el estado actual del sistema', 'Estado del Sistema — Larense C.A.\n\r\n12/09/2026 04:44\n\r\nClientes: 11\n\r\nProductos: 8 | Agotados: 0\n\r\nPedidos hoy: 0\n\r\nVentas del mes: $0.00\n\r\nPromociones activas: 5\n\r\nUsuarios del sistema: 8', NULL, '2026-09-11 22:44:01'),
(36, 1, NULL, 'Inventario', 'Genera un reporte en PDF con el estado del inventario', 'Estado del Inventario\n\r\nTotal productos: 8\n\r\nCon stock: 8\n\r\nAgotados: 0\n\r\nMayor stock: Galletas Natys Saladitas queso chedar 90g (5100 cajas)\n\r\nStock bajo (≤5 cajas): Todo el stock está en niveles normales', NULL, '2026-09-11 22:44:17'),
(37, 1, NULL, 'Ventas/Pagos', 'Observa el sistema y dame recomendaciones para mejorar', 'Estado del Sistema — Larense C.A.\n\r\n12/09/2026 04:44\n\r\nClientes: 11\n\r\nProductos: 8 | Agotados: 0\n\r\nPedidos hoy: 0\n\r\nVentas del mes: $0.00\n\r\nPromociones activas: 5\n\r\nUsuarios del sistema: 8', NULL, '2026-09-11 22:44:28'),
(38, 1, 'usuario', 'Clientes', 'Hola dame un analisis de los pedidos de los clientes y me das adicional un reporte estadistico referente a esto y en pdf', '', NULL, '2026-09-14 19:11:53'),
(39, 1, 'ia', NULL, '', '¡Hola! Con gusto te proporciono un análisis de los pedidos de tus clientes.\n\n**Análisis de Pedidos (Últimos 30 Días):**\n\n*   **Total de Pedidos:** Se han registrado **4** pedidos en los últimos 30 días.\n*   **Monto Total de Ventas:** El monto total generado por estos pedidos asciende a **$1725.00**.\n*   **Monto Promedio por Pedido:** Cada pedido tiene un valor promedio de **$431.25**.\n*   **Clientes con Pedidos:** **2** clientes diferentes han realizado pedidos en este período.\n\n📌 **Recomendaciones:**\n*   Considera implementar estrategias para aumentar la frecuencia de pedidos y el número de clientes activos.\n*   Analiza los productos más populares en estos pedidos para optimizar el inventario y las promociones.\n\nA continuación, te presento el reporte estadístico en formato PDF:\n\n<<<REPORTE>>>{\"titulo\":\"Análisis de Pedidos (Últimos 30 Días)\",\"columnas\":[\"Métrica\",\"Valor\"],\"filas\":[[\"Total Pedidos\",4],[\"Monto Total Ventas\",1725.00],[\"Monto Promedio Pedido\",431.25],[\"Clientes con Pedidos\",2]],\"totales\":{\"Monto Total Ventas\":1725.00},\"notas\":[\"Este reporte resume la actividad de pedidos en los últimos 30 días.\",\"Se recomienda incentivar la participación de más clientes.\"]}', NULL, '2026-09-14 19:11:53'),
(40, 1, 'usuario', 'General', 'Dime el estado actual del sistema', '', NULL, '2026-09-15 22:24:15'),
(41, 1, 'ia', NULL, '', '¡Hola! Parece que hubo un pequeño inconveniente al intentar obtener el estado completo del sistema en este momento. Sin embargo, puedo darte información clave:\n\n', NULL, '2026-09-15 22:24:15'),
(42, 1, 'usuario', 'Inventario', 'Genera un reporte en PDF con el estado del inventario', '', NULL, '2026-09-15 22:25:19'),
(43, 1, 'ia', NULL, '', '¡Claro que sí! Con gusto te genero un reporte del estado actual del inventario.\n\n', NULL, '2026-09-15 22:25:19'),
(44, 1, 'usuario', 'Ventas/Pagos', 'Observa el sistema y dame recomendaciones para mejorar', '', NULL, '2026-09-15 22:26:22'),
(45, 1, 'ia', NULL, '', '¡Lo siento mucho! Parece que hubo un problema técnico al intentar observar el sistema para generar las recomendaciones. Recibí un error que indica que hay una columna desconocida (`status_entrega`) en la base de datos al intentar calcular los insights.\n\nDebido a este inconveniente, no puedo proporcionarte recomendaciones en este momento. Te pido disculpas por la molestia. Por favor, intenta de nuevo más tarde o contacta al administrador del sistema si el problema persiste.', NULL, '2026-09-15 22:26:22'),
(46, 1, 'usuario', 'Clientes', 'Cuantos clientes tenemos', '', NULL, '2026-09-15 22:28:57'),
(47, 1, 'ia', NULL, '', '¡Tenemos 11 clientes registrados en el sistema!', NULL, '2026-09-15 22:28:57'),
(48, 1, 'usuario', 'General', 'Cual es la galleta mas vendida', '', NULL, '2026-09-15 22:30:07'),
(49, 1, 'ia', NULL, '', '¡Disculpa! Parece que hubo un pequeño problema técnico al intentar obtener el nombre de la galleta más vendida en este momento. El sistema me arrojó un error al procesar los datos de la consulta.\n\nPor favor, intenta de nuevo en unos momentos. Si el problema persiste, te agradecería que me lo hicieras saber.', NULL, '2026-09-15 22:30:07');

